{
  "lines": [
    {
      "text": "Reise-Tagebuch von Breslau nach Königsberg, im Sommer 1786."
    },
    {
      "text": "Den 12. Junius 1786 reiseten wir des Morgens um fünf Uhr von Breslau ab. Der"
    },
    {
      "text": "Herr von Jedliz hatte uns Briefe an die Magisträte der Städte mitgegeben, durch"
    },
    {
      "text": "welche wir kommen würden, und sein Bedienter begleitete uns bis vor das"
    },
    {
      "text": "Oder-Thor. Der Weg gieng über Neumarkt, wo wir die Pferde wechselten, nach"
    },
    {
      "text": "Liegniz, einer wohlgebauten Stadt an der Ratzbach, die wir gegen Abend"
    },
    {
      "text": "erreichten. Man zeigte uns das Schloß und die Ritter-Akademie, welche der"
    },
    {
      "text": "König im Jahre 1708 gestiftet hat."
    },
    {
      "text": "Den 14ten fuhren wir über Haynau nach Bunzlau. Die Töpfer-Waaren dieser"
    },
    {
      "text": "Stadt sind in ganz Schlesien berühmt, und wir kauften einige Krüge für unsere"
    },
    {
      "text": "Freunde in Berlin. Die Gegend ist fruchtbar, und die Dörfer sind besser gebauet"
    },
    {
      "text": "als in der Mark."
    },
    {
      "text": "Den 15ten kamen wir nach Görliz, wo wir zween Tage blieben. Der Rathsherr"
    },
    {
      "text": "Anton führte uns auf die Landeskrone, von welcher man das Riesengebirge sieht."
    },
    {
      "text": "In der Peterskirche sahen wir die Bibliothek, welche über zehntausend Bände"
    },
    {
      "text": "enthalten soll."
    }
  ],
  "script": "fraktur",
  "notes": "Printed page, single column, no visible damage or bleed-through. All text legible."
}

